  // Вопрос кнопкой: true — согласился
  function confirmDialog({ title, text, okLabel, danger = false, icon: ico, tone, warn = "", list }) {
    return new Promise((resolve) => {
      let done = false;
      const fin = (v) => { if (done) return; done = true; resolve(v); };
      const d = openDialog({ stack: true, alert: true, icon: ico || (danger ? "triangle-exclamation" : "circle-info"), tone: tone || (danger ? "danger" : "accent"), title, onClose: () => fin(false),
        blocks: [U.p(text, { lg: true }), list && list.length ? el("ul", { class: "kk-ul kk-ul--plain" }, list.map((x) => el("li", { text: x }))) : null, warn ? U.al("warning", null, warn) : null] });
      d.setFoot([U.btn(t("c.cancel"), "tertiary", () => { fin(false); d.close(); }, { md: true }), U.btn(okLabel || t("c.confirm"), danger ? "danger" : "primary", () => { fin(true); d.close(); }, { md: true })]);
    });
  }
  // Сообщение, которое обязано быть прочитано: одна кнопка «ОК»
