        const group = (label, rows) => el("div", { class: "kk-more__g" }, el("h2", { class: "kk-more__l", text: label }), K.mlist(rows));
        return [group(t("m.gConn"), conn), group(t("m.gTraffic"), traffic), group(t("m.gServer"), server),
          el("div", { class: "kk-more__foot" }, icon("circle-info", 16), el("span", {}, el("b", { text: v.ver }), v.seen ? el("span", { text: t("m.seenAt", { t: v.seen }) }) : null),
            U.btn(t("c.refresh"), "ghost", (ev, b) => manualRefresh(b), { md: true }))];
