      const seg = (cls, txt0) => el("span", { class: "gx-mtu__seg gx-mtu__seg--" + cls, text: txt0 });
      const sc = seg("c", ""), sh = seg("h", "+" + geo0.ov), s4 = geo0.s4 ? seg("s4", "S4 " + geo0.s4) : null;
