      const limT = el("span", { class: "is-lim", text: t("ps.limit", { n: mv.limit }) });
      const budT = el("span", { class: "is-bud", text: String(geo0.budget) });
      const bar = el("div", { class: "gx-mtu__bar" }, at(el("span", { class: "gx-mtu__over" }), geo0.bud), sc, sh, s4,
        mv.open ? at(el("i", { class: "gx-mtu__mk gx-mtu__mk--lim" }), geo0.lim) : null, at(el("i", { class: "gx-mtu__mk" }), geo0.bud));
      const graph = el("div", { class: "gx-mtu" + (mv.open ? "" : " is-off"), "aria-hidden": "true" },
        el("div", { class: "gx-mtu__top" }, mv.open ? at(limT, geo0.lim) : null, at(budT, geo0.bud)), bar,
        el("div", { class: "gx-mtu__ax" }, at(el("span", { class: "is-start", text: String(PS_LO) }), 0), at(el("span", { text: "1280" }), geo0.x1280),
          at(el("span", { text: String(geo0.budget) }), geo0.bud), at(el("span", { class: "is-end", text: String(geo0.nic) }), 100)));
      const mid = "psmtu-" + ibPpSeq;
