    d.body.replaceChildren(...[lastNode, el("div", { class: "gx-pset" }, el("div", { class: "gx-pset__main" }, portBlk, mtuBlk, tlsBlk), chg)].filter(Boolean));
    const sb = d.box.querySelector(".gx-sheet__sub");
    if (sb) sb.textContent = [st.groups.length ? st.groups.map((g) => g.cur + g.sfx).join(", ") : [ibPorts(r), t("ps.fixed")].filter(Boolean).join(" · "), mv ? "MTU " + mv.cur : "", tv ? "TLS " + psTlsText(tv, tv.cur) : "",
      tn("ps.devN", arr(view.devices).length)].filter(Boolean).join(" · ");
