  // Ц3: смена домена при VLESS на TLS — ссылки VLESS называют домен: выдать заново (строкой в вопросе смены домена)
  const vlDomainWarn = () => { const v = R.inbounds.loaded ? arr(R.inbounds.data).find((x) => x.kind === "vless" && x.installed) : null; return v && vlSec(v.record) === "tls" && Number(v.devices) > 0 ? tn("vl.domainPrice", Number(v.devices)) : ""; };
  // VLESS на TLS с устройствами — выключение сайта спросит цену (Ц1) вместо общего вопроса
  const vlTlsDevs = () => { const v = R.inbounds.loaded ? arr(R.inbounds.data).find((x) => x.kind === "vless" && x.installed) : null; return !!v && vlSec(v.record) === "tls" && Number(v.devices) > 0; };
  // Ц1–Ц4: окно цены — вопрос, что случится (первая строка — абзацем, остальные — списком со значками [текст, вид,
  // значок]; цена — жёлтым ключом), «Кому выдать заново» (первые три и «и ещё N»); фокус — на «Отмене»: ссылки людей
