      const li = (x) => el("li", { class: "gx-impact__i" + (x[1] ? " gx-impact__i--" + x[1] : "") },
        el("span", { class: "gx-impact__m" }, icon(x[2] || (x[1] ? "key" : "circle-info"), 14)), el("span", { text: x[0] }));
      const items = all.map(li);
