  // Выход не отвечает: почему и сколько (live: silent_since — первая неудачная проверка подряд), что с клиентами
  function exitDeadText(r) {
    const why = r.detail || t("ex.dead");
    const head = known(r.silent) ? t("ex.deadFor", { why, d: fmtDur(r.silent) }) : why;
    return r.enabled ? head + ". " + t(r.others > 0 ? "ex.clientsMove" : "ex.noOthers") : head;
  }
  // Выход работает, но проверки не проходят (3.3.5): правило «упал» решает от EXIT_MIN_CHECKS проверок в окне 2 мин
  // (kaskad.gw.exits.MIN_TRIES) — пока их меньше и не прошла половина, не «работает», а «проверяется» (REV-335 №4)
  const EXIT_MIN_CHECKS = 4;
  function exitSilentText(r) {
    const of = r.dies || r.fails;
    const few = of < EXIT_MIN_CHECKS && 2 * r.fails >= of;
    return t(few ? "ex.silentFew" : "ex.silentCheck", { d: fmtDur(r.silent), i: r.fails, of, min: EXIT_MIN_CHECKS });
  }
  // Строки выходов с живыми данными сборщика: рукопожатие ноги AmneziaWG и тишина — по своим часам (live.json раз в 10 с)
  function exitRows() {
    if (!R.exits.loaded) return [];
    const nowS = Date.now() / 1000;
    const rows = R.exits.data.rows.map((r) => {
      const lv = lvExit(r.id);
      const pick = (k, dflt) => (lv && k in lv ? lv[k] : dflt);
      const hsAt = num(pick("handshake_at", null));
      const silAt = num(pick("silent_since", r.silentSince));
      return Object.assign({}, r, { state: exitState(r), detail: (lv && lv.detail) || r.detail, since: (lv && lv.since) || r.since,
        hs: hsAt ? Math.max(0, Math.round(nowS - hsAt)) : null, silent: silAt ? Math.max(0, Math.round(nowS - silAt)) : null,
        fails: num(pick("fails", r.fails)) || 0, dies: num(pick("dies_after", r.diesAfter)) });
    });
    // others — рабочие выходы той же роли (как ops.exits_view): российский домашний роутер зарубежный не подменит
    const working = (role) => rows.filter((r) => r.enabled && r.state === "alive" && (r.role === "ru") === role).length;
    rows.forEach((r) => { r.others = working(r.role === "ru") - (r.enabled && r.state === "alive" ? 1 : 0); });
    return rows;
  }
  // Подписки выходов (GET gw/exits: subs — exitsubs.public, адреса в ответе нет). Карточка видна, когда подписки есть:
  // имя (домен или «подписка N»), состояние словами сервера (не обновлялась давно или с ошибкой — предупреждением),
