    const d0 = R.rules.data, gs = d0.ru_groups.filter((g) => isObj(g) && g.id);
    if (!gs.length) { goNav("exits", { tab: "ru" }); return; }
    const users = arr(d0.users).filter((u) => isObj(u) && u.id).slice().sort((a, b) => String(a.name || "").localeCompare(String(b.name || ""), LANG));
    const base = Object.create(null), draft = Object.create(null), vers = Object.create(null);
    users.forEach((u) => { base[u.id] = typeof u.ru_via === "string" ? u.ru_via : "inherit"; vers[u.id] = typeof u.ru_ver === "string" ? u.ru_ver : ""; });
    const st = { g: gs.some((g) => g.id === gid0) ? gid0 : gs[0].id, q: "" };
    const val = (id) => (id in draft ? draft[id] : base[id]);
    const gName = (gid) => { const g = gs.find((x) => x.id === gid); return g ? rsName(g) : gid; };
    const isG = (via) => gs.some((g) => g.id === via);
    const word = (via) => (isG(via) ? t("rs.viaG", { g: gName(via) }) : t("rs.direct"));               // «сейчас: …»
    const short = (via) => (isG(via) ? t("fmt.quote", { name: gName(via) }) : t("rs.directS"));        // «Изменится: …»
    const prof = (u) => (known(u.rules) && u.rules !== "inherit" ? String(u.rules) : String(d0.default || ""));
    const profName = (p) => (p === "all_exit" ? t("ru.pAll") : p === "ru_direct" ? t("ru.pRu") : p);
    const tabs = el("div");
    const q = el("input", { type: "search", placeholder: t("rs.searchPh"), "aria-label": t("rs.searchPh"), autocomplete: "off", spellcheck: "false", maxlength: "64" });
    q.addEventListener("input", () => { st.q = q.value.trim().toLowerCase(); drawList(); });
    const list = el("div", { class: "kk-ulist", role: "group", "aria-label": t("rs.listL") });
    const sum = el("div", { class: "kk-psum", "aria-live": "polite" });
    const note = el("p", { class: "kk-rsnote" }, icon("circle-info", 14), el("span", { text: t("rs.provider") }));
