      if (!x || /\s/.test(x) || x.length > 253) { err.textContent = t(x ? "ru.traceBad" : "ru.traceEmpty"); qIn.setAttribute("aria-invalid", "true"); qIn.focus(); return; }
      traceNav((TRACE_WHO.test(RU_TRACE.who) ? RU_TRACE.who : "-") + ":" + x);
