  // ── 22. Настройки ────────────────────────────────────────────────────────
  function tunnelCommand() {
    const p = R.panel.data && R.panel.data.tunnel;
    if (p) return String(p);
    const port = location.port || "1980";
    const host = (R.gw.data && R.gw.data.host) || t("st.nodeAddr");
    return "ssh -L " + port + ":127.0.0.1:" + port + " root@" + host;
  }
  // Одно и то же — один раз за раз: пока такое окно открыто (single) или запрос идёт (oneAtATime), повторный щелчок
  // (двойной клик, Enter и клик) ничего не делает. Второй PUT пароля шёл бы со старой сессией, которую первый уже
  // закрыл; второе включение доступа из интернета взяло бы второй порт; второй ключ — второе окно установки.
  const singles = {};
  function single(key, open) {
    const cur = singles[key];
    if (cur && cur.isConnected) return null;
    const d = open();
    singles[key] = d && d.el ? d.el : null;
    return d;
  }
  const running = new Set();
  async function oneAtATime(key, fn) {
    if (running.has(key)) return null;
    running.add(key);
    try { return await fn(); } finally { running.delete(key); }
  }
  // Порт туннеля — из самой команды (ssh -L 1980:…): открытая из интернета панель живёт на другом порту
  const tunnelPort = (cmd) => { const m = /-L\s+(\d+):/.exec(String(cmd || "")); return m ? m[1] : "1980"; };
  const VIA_TEXT = { tunnel: "st.viaTunnel", password: "st.viaPassword", link: "st.viaLink" };
  const curVia = () => S.via || (R.panel.data && R.panel.data.via) || "";
  // Зашли в панель из интернета: сервер знает, через какой слушатель пришёл запрос (GET session: scheme https)
  const fromInternet = () => S.scheme === "https" || (curVia() !== "tunnel" && location.protocol === "https:");
  // Каким путём открыта эта вкладка: local — SSH-туннель, public — порт (открытый режим), proxy — домен через nginx.
  // Сервер говорит сам (GET session: listener): с 3.3.7.5 секретный путь есть и на порту, по BASE домен не отличить
