    const tunnelTab = curVia() === "tunnel";
    const np = needPw ? newPasswordField(t("st.pwNew"), { value: genPassword(), show: true, hint: t("st.pubPwSave") }) : null;
    const curIn = !needPw && tunnelTab ? U.input({ type: "password", ac: "current-password", max: 200, aria: t("st.pubPw") }) : null;
