    hcLazy(sched, () => loadPage("diag"), (p) => { if (hc.diag && hc.diag !== p && hc.diag.leave) hc.diag.leave(); hc.diag = p; p.schedule(sched); });
    hcLazy(speed, () => loadPart("exits-groups"), (pt) => { hc.speed = pt; speed.append(pt.speedCard({ open: true })); });
    return out;
