      if (MOCK && LANG === "en") { try { await loadScript("dev-mock-en.js"); } catch (e) { /* демо-данные по-русски */ } }
      if (MOCK) { try { await loadScript("dev-mock-ux.js"); } catch (e) { /* без демо бота, ключа агента и журнала */ } }
      if (MOCK) { try { await loadScript("dev-mock-diag.js"); } catch (e) { /* без расписания и истории проверок */ } }
      if (MOCK) { try { await loadScript("dev-mock-speed.js"); } catch (e) { /* без замера от устройства до сервера */ } }
      if (MOCK) { try { await loadScript("dev-mock-regroup.js"); } catch (e) { /* без «Разложить заново» (F14) */ } }
      if (MOCK) { try { await loadScript("dev-mock-adr.js"); } catch (e) { /* без «Адресов сервера» (F10–F13) */ } }
      const scene = QS.get("scene") || "";                         // сцена «как на узле»: записанные ответы живого узла
      if (MOCK && /^[a-z0-9]{1,32}$/.test(scene)) { try { await loadScript("dev-mock-scene-" + scene + ".js"); await loadScript("dev-mock-scene.js"); } catch (e) { /* нет сцены — обычная заглушка */ } }
